<?php
/** Slice 1 proof — folders: My files, create, rename, colour, duplicates, slashes, the crumbs, move with the picker and its refusals, the listing's sort/filter/paging, multi-select, trash and restore, the access line (spec "Proof" 1–4, 13). */
require __DIR__ . '/lib.php';
$seed = seed_store();
$priyaRoot = root_of(26);
$boardRoot = $seed['board_root'];
$contracts = $seed['contracts'];

echo "1. My files, the root, the empty state\n";
$r = page(actor(26), '/files/');
ok($r['code'] === 302 && str_ends_with($r['location'], '/f/' . $priyaRoot), "My files 302s a member to their personal root (/f/$priyaRoot)");
$r = page(actor(29), '/files/');
ok($r['code'] === 302 && str_ends_with($r['location'], '/shared/'), 'a guest is sent to Shared with me');
$danaRoot = root_of(30);
$b = page(actor(30), '/f/' . $danaRoot)['body'];
ok(str_contains($b, 'Nothing here yet.') && str_contains($b, 'id="folder-new-btn"') && str_contains($b, 'id="folder-upload-btn"'), 'an empty personal root says "Nothing here yet." with New folder and (disabled) Upload');
ok(str_contains($b, 'id="folder-access-text">Only you<'), 'the access line of a personal root reads "Only you"');
$b = page(actor(26), '/f/' . $boardRoot)['body'];
ok(str_contains($b, 'id="folder-access-text">SMOKE Board · 3 people · 1 group<'), 'the access line of the group root reads "SMOKE Board · 3 people · 1 group"');
ok(str_contains($b, 'id="listing-row-folder-' . $contracts . '"') && str_contains($b, 'href="/f/' . $contracts . '?back='), 'the listing shows Contracts as a folder row linking to /f/{id} with ?back=');
ok(str_contains(page(actor(26), '/f/' . $contracts)['body'], 'id="listing-row-document-' . $seed['board_doc'] . '"'), '...and Contracts lists its document');

echo "2. Create, rename, colour, duplicates, slashes, crumbs\n";
$r = post(27, '/folders/save.php', ['parent' => $contracts, 'name' => '2026', 'colour' => '#3454d1']);
$f2026 = (int) one('SELECT id FROM folders WHERE parent_id = :p AND name = :n', ['p' => $contracts, 'n' => '2026']);
ok($r['code'] === 302 && $f2026 > 0 && str_ends_with($r['location'], '/f/' . $f2026 . '?notice=created'), "folder_create lands on the new folder with the notice (/f/$f2026)");
$ev = last_event('folder.create');
ok($ev !== null && (int) $ev['folder_id'] === $f2026 && (int) $ev['entity_id'] === $f2026 && (int) $ev['library_id'] === (int) one('SELECT library_id FROM folders WHERE id = :id', ['id' => $f2026]) && json_decode($ev['after'], true)['parent_id'] === $contracts, 'folder.create logged with folder_id, library_id and the parent');
ok(one('SELECT colour FROM folders WHERE id = :id', ['id' => $f2026]) === '#3454d1' && (int) one('SELECT owner_member_id FROM folders WHERE id = :id', ['id' => $f2026]) === 27, 'the colour is kept and the maker owns the folder');
$r = post(27, '/folders/save.php', ['parent' => $contracts, 'name' => '2026']);
ok($r['code'] === 422 && str_contains($r['body'], 'A folder of that name is already here.'), 'a duplicate name is refused in words (422)');
$r = post(27, '/folders/save.php', ['parent' => $contracts, 'name' => 'A/B']);
ok($r['code'] === 422 && str_contains($r['body'], 'no slash'), 'a slash in a name is refused');
$r = post(27, '/folders/save.php', ['parent' => $contracts, 'name' => '']);
ok($r['code'] === 422 && str_contains($r['body'], 'Give the folder a name.'), 'an empty name is refused');
$r = post(27, '/folders/save.php', ['folder' => $f2026, 'name' => 'Year 2026']);
ok($r['code'] === 302 && one('SELECT name FROM folders WHERE id = :id', ['id' => $f2026]) === 'Year 2026' && last_event('folder.rename') !== null && json_decode(last_event('folder.rename')['before'], true)['name'] === '2026', 'folder_rename renames and logs before/after');
$r = post(27, '/folders/save.php', ['folder' => $f2026, 'colour' => '#ef4444']);
ok($r['code'] === 302 && one('SELECT colour FROM folders WHERE id = :id', ['id' => $f2026]) === '#ef4444' && json_decode(last_event('folder.update')['after'], true)['colour'] === '#ef4444', 'folder_update sets the colour and logs folder.update');
$r = post(27, '/folders/save.php', ['folder' => $f2026, 'colour' => 'red']);
ok($r['code'] === 422 && str_contains($r['body'], 'eight colours'), 'a colour not among the eight is refused');
$r = post(27, '/folders/save.php', ['folder' => $boardRoot, 'name' => 'Renamed root']);
ok($r['code'] === 422 && str_contains($r['body'], 'root is renamed with the library'), 'a root is not renamed here');
post(27, '/folders/save.php', ['parent' => $f2026, 'name' => 'Q1']);
$q1 = (int) one('SELECT id FROM folders WHERE parent_id = :p AND name = :n', ['p' => $f2026, 'n' => 'Q1']);
$b = page(actor(27), '/f/' . $q1)['body'];
preg_match_all('/id="folder-crumb-(\d+)"/', $b, $m);
ok($m[1] === [(string) $boardRoot, (string) $contracts, (string) $f2026, (string) $q1] && substr_count($b, 'breadcrumb-item active') === 1, 'the crumbs after a nested create: root › Contracts › Year 2026 › Q1, every one a link but the last');
$r = post(27, '/folders/auto-tags.php', ['folder' => $f2026, 'auto_tags' => 'Contract, 2026 Deals']);
ok($r['code'] === 302 && one('SELECT auto_tags::text FROM folders WHERE id = :id', ['id' => $f2026]) === '{contract,2026-deals}' && json_decode(last_event('folder.auto_tags')['after'], true)['auto_tags'] === ['contract', '2026-deals'], 'folder_auto_tags_set stores slugs and logs them');

echo "3. Move: the picker, refusals, the subtree follows\n";
$r = page(actor(27), '/folders/' . $f2026 . '/move');
ok($r['code'] === 200 && str_contains($r['body'], 'data-picker-source="folder"') && str_contains($r['body'], 'name="target_folder"') && str_contains($r['body'], 'SMOKE Board › Contracts › Year 2026'), 'the move screen carries the picker over folders and the current path');
$pk = page(actor(27), '/pick/?source=folder&q=minutes')['body'];
ok(str_contains($pk, 'record-picker-empty'), 'the folder picker searches: nothing named minutes yet');
post(27, '/folders/save.php', ['parent' => $boardRoot, 'name' => 'Minutes']);
$minutes = (int) one('SELECT id FROM folders WHERE parent_id = :p AND name = :n', ['p' => $boardRoot, 'n' => 'Minutes']);
$pk = page(actor(27), '/pick/?source=folder&q=minut')['body'];
ok(str_contains($pk, 'record-picker-row-' . $minutes) && str_contains($pk, 'SMOKE Board › Minutes'), '...and finds Minutes by its name, labelled with its path');
$pk = page(actor(26), '/pick/?source=folder&library=' . (int) one('SELECT library_id FROM folders WHERE id = :id', ['id' => $priyaRoot]))['body'];
ok(str_contains($pk, 'record-picker-row-' . $priyaRoot) && !str_contains($pk, 'record-picker-row-' . $boardRoot), 'the library param narrows the picker to one library');
$r = post(27, '/folders/move.php', ['folder' => $contracts, 'target_folder' => $q1]);
ok($r['code'] === 422 && str_contains($r['body'], 'cannot move under itself'), 'a move under itself is refused with the database\'s words');
$r = post(27, '/folders/move.php', ['folder' => $f2026, 'target_folder' => root_of(27)]);
ok($r['code'] === 422 && str_contains($r['body'], 'within its library'), 'a move to another library is refused');
$r = post(27, '/folders/move.php', ['folder' => $boardRoot, 'target_folder' => $minutes]);
ok($r['code'] === 422 && str_contains($r['body'], 'never moves'), 'a root never moves');
$r = post(27, '/folders/move.php', ['folder' => $f2026, 'target_folder' => $minutes]);
ok($r['code'] === 302 && (int) one('SELECT parent_id FROM folders WHERE id = :id', ['id' => $f2026]) === $minutes, 'a move with the picker lands on the folder');
$b = page(actor(27), '/f/' . $q1)['body'];
preg_match_all('/id="folder-crumb-(\d+)"/', $b, $m);
ok($m[1] === [(string) $boardRoot, (string) $minutes, (string) $f2026, (string) $q1] && one('SELECT depth FROM folders WHERE id = :id', ['id' => $q1]) === 3, 'the subtree\'s crumbs and depth follow the move');
$ev = last_event('folder.move');
ok((int) json_decode($ev['before'], true)['parent_id'] === $contracts && (int) json_decode($ev['after'], true)['parent_id'] === $minutes, 'folder.move logged with before/after parent_id');
$r = post(27, '/folders/move.php', ['folder' => $f2026, 'target_folder' => $contracts]);
ok($r['code'] === 302, '...and back to Contracts');
$r = post(26, '/folders/move.php', ['folder' => $f2026, 'target_folder' => root_of(30)]);
ok($r['code'] === 404, 'a target the mover may not see is Not found (the same nothing)');

echo "4. The listing: sort, filter, paging, multi-select\n";
pdo()->exec("SELECT set_config('app.member_id', '27', false)");
for ($i = 1; $i <= 105; $i++) {
    pdo()->prepare('INSERT INTO folders (library_id, parent_id, name, owner_member_id, created_by) VALUES ((SELECT library_id FROM folders WHERE id = :p), :p, :n, 27, 27)')->execute(['p' => $minutes, 'n' => sprintf('Week %03d', $i)]);
}
$b = page(actor(27), '/f/' . $minutes)['body'];
preg_match_all('/id="listing-row-folder-(\d+)"/', $b, $m);
ok(count($m[1]) === 100 && str_contains($b, 'id="listing-next"') && !str_contains($b, 'id="listing-prev"') && str_contains($b, 'page 1 of 2'), '100 rows a page, a Next link, page 1 of 2 (105 subfolders)');
$b2 = page(actor(27), '/f/' . $minutes . '?page=2')['body'];
preg_match_all('/id="listing-row-folder-(\d+)"/', $b2, $m2);
ok(count($m2[1]) === 5 && str_contains($b2, 'id="listing-prev"'), 'page 2 holds the last five with a Previous link');
$names = static function (string $html): array { preg_match_all('/id="listing-link-folder-\d+"[^>]*>([^<]+)</', $html, $mm); return $mm[1]; };
$asc = $names(page(actor(27), '/f/' . $minutes . '?sort=name&dir=asc')['body']);
$desc = $names(page(actor(27), '/f/' . $minutes . '?sort=name&dir=desc')['body']);
ok($asc[0] === 'Week 001' && $asc[99] === 'Week 100' && $desc[0] === 'Week 105' && $desc[1] === 'Week 104', 'sort by name both ways');
pdo()->prepare('UPDATE folders SET updated_at = now() + interval \'1 hour\' WHERE parent_id = :p AND name = :n')->execute(['p' => $minutes, 'n' => 'Week 007']);
$upd = $names(page(actor(27), '/f/' . $minutes . '?sort=updated&dir=desc')['body']);
ok($upd[0] === 'Week 007', 'sort by updated, newest first');
$b = page(actor(27), '/f/' . $contracts . '?kind=document')['body'];
ok(str_contains($b, 'id="listing-row-document-' . $seed['board_doc'] . '"') && !str_contains($b, 'id="listing-row-folder-' . $f2026 . '"'), 'the kind filter "document" hides the folders');
$b = page(actor(27), '/f/' . $contracts . '?kind=pdf')['body'];
ok(str_contains($b, 'id="listing-row-document-' . $seed['board_doc'] . '"'), '...and "pdf" keeps the PDF');
$b = page(actor(27), '/f/' . $contracts . '?kind=image')['body'];
ok(str_contains($b, 'Nothing of that kind here.'), '...and "image" finds nothing, in words');
$sz = page(actor(27), '/f/' . $contracts . '?sort=size&dir=desc')['body'];
ok(str_contains($sz, 'id="listing-sort-size"') && str_contains($sz, 'feather-chevron-down'), 'the size header shows the sort direction');
$b = page(actor(27), '/f/' . $minutes)['body'];
ok(str_contains($b, 'id="select-bar"') && str_contains($b, 'name="folder[]"') && str_contains($b, 'form="select-bar"') && str_contains($b, 'id="select-bar-target"'), 'the multi-select bar and the row checkboxes are there for an editor');
$w1 = (int) one("SELECT id FROM folders WHERE parent_id = :p AND name = 'Week 001'", ['p' => $minutes]);
$w2 = (int) one("SELECT id FROM folders WHERE parent_id = :p AND name = 'Week 002'", ['p' => $minutes]);
$r = post(27, '/folders/move.php', ['folder' => [$w1, $w2], 'target_folder' => $f2026, 'return_to' => '/f/' . $minutes]);
ok($r['code'] === 302 && (int) one('SELECT parent_id FROM folders WHERE id = :id', ['id' => $w1]) === $f2026 && (int) one('SELECT parent_id FROM folders WHERE id = :id', ['id' => $w2]) === $f2026 && str_ends_with($r['location'], '/f/' . $minutes . '?notice=moved_many'), 'a multi-select move of two folders lands back on the listing');
$b = page(actor(26), '/f/' . $minutes)['body'];
ok(!str_contains($b, 'id="folder-trash-btn"') && str_contains($b, 'id="folder-edit-btn"'), 'a group member at edit sees Rename and Move but no Trash (manage)');
$b = page(actor(27), '/f/' . $minutes)['body'];
ok(str_contains($b, 'id="folder-trash-btn"'), 'the owner sees Trash');

echo "5. Trash and restore (the actions; the trash screen is slice 6's)\n";
$r = post(26, '/folders/trash.php', ['folder' => $f2026]);
ok($r['code'] === 403 && str_contains($r['body'], 'You may not manage this folder.'), 'a member at edit may not trash: 403 in words');
$r = post(27, '/folders/trash.php', ['folder' => $f2026]);
ok($r['code'] === 302 && one('SELECT trashed_at IS NOT NULL FROM folders WHERE id = :id', ['id' => $f2026]) === true && one('SELECT trashed_at IS NOT NULL FROM folders WHERE id = :id', ['id' => $q1]) === true && str_ends_with($r['location'], '/f/' . $contracts . '?notice=trashed'), 'folder_trash takes the subtree and lands on the parent');
ok(page(actor(27), '/f/' . $f2026)['code'] === 404 && !str_contains(page(actor(27), '/f/' . $contracts)['body'], 'id="listing-row-folder-' . $f2026 . '"'), 'a trashed folder is Not found on its page and gone from the listing');
$ev = last_event('folder.trash');
ok((int) json_decode($ev['after'], true)['folders'] === 4 && (int) $ev['folder_id'] === $f2026, 'folder.trash logged with the count of folders taken (Year 2026, Q1, Week 001, Week 002)');
$r = post(27, '/folders/restore.php', ['folder' => $f2026]);
ok($r['code'] === 302 && one('SELECT trashed_at IS NULL FROM folders WHERE id = :id', ['id' => $q1]) === true, 'folder_restore brings the subtree back');
$r = post(27, '/folders/trash.php', ['folder' => $boardRoot]);
ok($r['code'] === 422 && str_contains($r['body'], 'never trashed'), 'a root is never trashed');

echo "6. The walls on folders\n";
ok(page(actor(29), '/f/' . $contracts)['code'] === 404 && page(actor(28), '/f/' . $contracts)['code'] === 404, 'a guest and a member outside the group get 404 on a group folder');
ok(page(actor(28), '/folders/new?parent=' . $contracts)['code'] === 404, '...and 404 on its New folder form');
$r = post(28, '/folders/save.php', ['parent' => $contracts, 'name' => 'Intruder']);
ok($r['code'] === 404, '...and a create there is Not found');
$r = post(29, '/folders/save.php', ['parent' => $contracts, 'name' => 'Intruder']);
ok($r['code'] === 403 && str_contains($r['body'], 'You may not'), 'a guest holds no documents.upload: 403 in words');
pdo()->exec("SELECT set_config('app.member_id', '27', false)");
pdo()->exec("INSERT INTO folder_access (folder_id, principal_kind, principal_id, level, granted_by) VALUES ($contracts, 'member', 28, 'view', 27) ON CONFLICT DO NOTHING");
ok(page(actor(28), '/f/' . $contracts)['code'] === 200, 'Bea given view on Contracts opens it');
$r = post(28, '/folders/save.php', ['parent' => $contracts, 'name' => 'Viewer folder']);
ok($r['code'] === 403 && str_contains($r['body'], 'You may not add to this folder.'), '...but a viewer cannot create a subfolder: 403 in words');
$b = page(actor(28), '/f/' . $contracts)['body'];
ok(!str_contains($b, 'id="folder-new-btn"') && !str_contains($b, 'id="select-bar"') && str_contains($b, 'id="folder-star-btn"'), 'a viewer sees no New folder and no select bar, but may star');
ok(str_contains($b, 'id="folder-access-text">SMOKE Board · 1 person · 1 group<'), 'the access line counts the explicit rows: "SMOKE Board · 1 person · 1 group"');
pdo()->exec("DELETE FROM folder_access WHERE folder_id = $contracts");
ok(page(actor(28), '/f/' . $contracts)['code'] === 404, 'the row removed, Bea is out again');
$b = page(actor(1), '/f/' . $priyaRoot)['body'];
ok(page(actor(1), '/f/' . $priyaRoot)['code'] === 200 && str_contains($b, 'id="folder-admin-view"'), 'the admin opens a member\'s personal library and is told it is the admin\'s view');
finish();
